import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import MapWithAutoFill from "../MapWithAutoFill";
import "./HousePredictionForm.css";

export default function HousePredictionForm() {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    location: "",
    latitude: null,
    longitude: null,
    area: "",
    propertyType: "",
    bedrooms: "",
    bathrooms: "",
    year: new Date().getFullYear(),
    condition: "",
    hospitalApplicable: "notApplicable",
    hospitalDistance: 0,
    schoolApplicable: "notApplicable",
    schoolDistance: 0,
    railwayApplicable: "notApplicable",
    railwayDistance: 0,
    busApplicable: "notApplicable",
    busDistance: 0,
  });

  const [result, setResult] = useState();
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleAutoFill = (data) => {
    setForm((prev) => ({
      ...prev,
      location: data.location || prev.location,
      latitude: data.latitude || prev.latitude,
      longitude: data.longitude || prev.longitude,
      hospitalApplicable: data.hospitalApplicable || prev.hospitalApplicable,
      hospitalDistance: data.hospitalDistance || prev.hospitalDistance,
      schoolApplicable: data.schoolApplicable || prev.schoolApplicable,
      schoolDistance: data.schoolDistance || prev.schoolDistance,
      railwayApplicable: data.railwayApplicable || prev.railwayApplicable,
      railwayDistance: data.railwayDistance || prev.railwayDistance,
      busApplicable: data.busApplicable || prev.busApplicable,
      busDistance: data.busDistance || prev.busDistance,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setResult();

    try {
      const res = await fetch(`${process.env.REACT_APP_BACKEND_URL}/predict/house`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });
      const data = await res.json();
      setResult(data.price);
    } catch (err) {
      setResult("Prediction failed.");
    }

    setLoading(false);
  };

  const renderFacility = (label, applicableName, distanceName) => (
    <div key={applicableName} className="form-group">
      <label>{label}</label>
      <div>
        <label>
          <input
            type="radio"
            name={applicableName}
            value="applicable"
            checked={form[applicableName] === "applicable"}
            onChange={handleChange}
          />
          Applicable
        </label>
        <label>
          <input
            type="radio"
            name={applicableName}
            value="notApplicable"
            checked={form[applicableName] === "notApplicable"}
            onChange={handleChange}
          />
          Not Applicable
        </label>
      </div>
      {form[applicableName] === "applicable" && (
        <input
          type="number"
          name={distanceName}
          min="0"
          step="0.1"
          placeholder={`Distance from ${label} (km)`}
          value={form[distanceName]}
          onChange={handleChange}
          required
        />
      )}
    </div>
  );

  return (
    <div className="house-predict-root">
      <button className="back-btn" onClick={() => navigate("/")}>
        ← Back to Home
      </button>
      <div className="house-predict-panels">
        <div className="property-details-card">
          <h2>Property Details</h2>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Location</label>
              <input
                name="location"
                type="text"
                placeholder="Location"
                value={form.location}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label>Choose Location on Map:</label>
              <MapWithAutoFill
                initialLat={form.latitude}
                initialLng={form.longitude}
                onAutoFill={handleAutoFill}
              />
              {!!form.latitude && !!form.longitude && (
                <div>
                  Selected: {form.latitude.toFixed(4)}, {form.longitude.toFixed(4)}
                </div>
              )}
            </div>

            <div className="form-group">
              <label>Area (sq ft)</label>
              <input
                type="number"
                name="area"
                value={form.area}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label>Property Type</label>
              <select
                name="propertyType"
                value={form.propertyType}
                onChange={handleChange}
                required
              >
                <option value="">Select type</option>
                <option>Apartment</option>
                <option>Villa</option>
                <option>Independent House</option>
                <option>Duplex</option>
              </select>
            </div>

            <div className="form-group">
              <label>Bedrooms</label>
              <select
                name="bedrooms"
                value={form.bedrooms}
                onChange={handleChange}
                required
              >
                <option value="">Select</option>
                {[1, 2, 3, 4, 5].map((num) => (
                  <option key={num} value={num}>
                    {num}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label>Bathrooms</label>
              <select
                name="bathrooms"
                value={form.bathrooms}
                onChange={handleChange}
                required
              >
                <option value="">Select</option>
                {[1, 2, 3, 4, 5].map((num) => (
                  <option key={num} value={num}>
                    {num}
                  </option>
                ))}
              </select>
            </div>

            <div className="form-group">
              <label>Year Built</label>
              <input
                type="number"
                name="year"
                min="1900"
                max={new Date().getFullYear()}
                value={form.year}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label>Condition</label>
              <select name="condition" value={form.condition} onChange={handleChange} required>
                <option value="">Select</option>
                <option>Excellent</option>
                <option>Good</option>
                <option>Needs Renovation</option>
              </select>
            </div>

            {/* Facilities */}
            {renderFacility("Hospital", "hospitalApplicable", "hospitalDistance")}
            {renderFacility("School", "schoolApplicable", "schoolDistance")}
            {renderFacility("Railway Station", "railwayApplicable", "railwayDistance")}
            {renderFacility("Bus Stand", "busApplicable", "busDistance")}

            <button type="submit" className="predict-btn" disabled={loading}>
              {loading ? "Predicting..." : "Predict House Price"}
            </button>
          </form>
        </div>

        <div className="price-prediction-card">
          <h2>Price Prediction</h2>
          {result ? (
            <div className="price-result">₹ {result}</div>
          ) : (
            <div className="result-placeholder">Fill out the form to see your price prediction</div>
          )}
        </div>
      </div>
    </div>
  );
}
